/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(tableStr(BOMCalcTransDetailUnionAll))]
final class AVABOMCalcTransDetailUnionAll_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <returns>InventQtyConsumption</returns>
public display InventQtyConsumption AVAConsumptionSum()
{
    if(this.displayUnitId() == "@SYS1151")
    {
        return this.consumptionSum() * 60;
    }
    else
    {
        return this.consumptionSum();
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>real</returns>
public display real AVARouteOprTime()
{
    if(this.displayUnitId() == "@SYS1151")
    {
        return this.consumptionSum() / 0.0167;
    }

    return 0;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>WrkCtrLoadPct</returns>
public display WrkCtrLoadPct        AVAWrkCtrLoadPct()
{
    BOMCalcTrans    locBOMCalcTrans;
    RouteOpr        routeOpr;

    WrkCtrRouteOprActivity              wrkCtrRouteOprActivity;
    WrkCtrActivity                      wrkCtrActivity;
    WrkCtrActivityRequirementSet        wrkCtrActivityRequirementSet;
    WrkCtrActivityRequirement           wrkCtrActivityRequirement;
    //WrkCtrActivityResourceRequirement   wrkCtrActivityResourceRequirement;
    WrkCtrResourceGroupResource         wrkCtrResourceGroupResource;
    WrkCtrActivityResourceGroupRequirement   wrkCtrActivityResourceGroupRequirement;

    ;

    while select * from locBOMCalcTrans where locBOMCalcTrans.PriceCalcId == this.PriceCalcId
            && (locBOMCalcTrans.CalcType == ItemCalcType::Item || locBOMCalcTrans.CalcType == ItemCalcType::Production || locBOMCalcTrans.CalcType == ItemCalcType::BOM)
            && locBOMCalcTrans.Level == this.Level - 1
    {
        select firstonly wrkCtrResourceGroupResource
            where wrkCtrResourceGroupResource.WrkCtrId == this.Resource
               join wrkCtrActivityResourceGroupRequirement
                    where wrkCtrActivityResourceGroupRequirement.ResourceGroup == wrkCtrResourceGroupResource.ResourceGroup
                           join wrkCtrActivityRequirement
                                where wrkCtrActivityRequirement.RecId == wrkCtrActivityResourceGroupRequirement.ActivityRequirement
                            join     wrkCtrActivityRequirementSet
                                where  wrkCtrActivityRequirementSet.RecId ==  wrkCtrActivityRequirement.ActivityRequirementSet
                            join wrkCtrActivity
                                where wrkCtrActivity.RecId == wrkCtrActivityRequirementSet.Activity
                         join wrkCtrRouteOprActivity
                            where wrkCtrRouteOprActivity.Activity == wrkCtrActivity.RecId
                                join routeOpr
                                    where routeOpr.RecId == wrkCtrRouteOprActivity.RouteOpr
                                         && routeOpr.ItemRelation == locBOMCalcTrans.Resource;

        if (routeOpr)
        {
            return wrkCtrActivityRequirementSet.LoadPercent;
        }
    }

    return 0;

}
